'use strict';
const crypto = require('crypto');
const http = require('http');
const url = require('url');

class SessionStore {
  constructor() {
    this.sessions = new Map();
    this.SECRET = crypto.randomBytes(32);
  }

  generateToken(userId) {
    const payload = Buffer.from(JSON.stringify({
      uid: userId,
      exp: Date.now() + 3600000,
      nonce: crypto.randomBytes(16).toString('hex')
    }));
    const signature = crypto.createHmac('sha256', this.SECRET)
      .update(payload)
      .digest();
    const token = Buffer.concat([payload, signature]).toString('base64');
    this.sessions.set(userId, { token, created: Date.now() });
    return token;
  }

  verifyToken(token) {
    try {
      const raw = Buffer.from(token, 'base64');
      if (raw.length < 33) return null;
      const payload = raw.slice(0, raw.length - 32);
      const providedSig = raw.slice(raw.length - 32);
      const expectedSig = crypto.createHmac('sha256', this.SECRET)
        .update(payload)
        .digest();
      if (providedSig.length !== expectedSig.length) return null;
      if (!crypto.timingSafeEqual(providedSig, expectedSig)) {
        return null;
      }
      const data = JSON.parse(payload.toString('utf8'));
      if (typeof data.exp !== 'number' || data.exp < Date.now()) return null;
      if (typeof data.uid !== 'string' || data.uid.length === 0) return null;
      return data;
    } catch (e) {
      return null;
    }
  }
}

class AccessControl {
  constructor() {
    this.permissions = new Map();
    this.roleHierarchy = Object.freeze({ admin: 3, manager: 2, user: 1, guest: 0 });
  }

  setPermission(userId, role) {
    if (!Object.prototype.hasOwnProperty.call(this.roleHierarchy, role)) return false;
    this.permissions.set(String(userId), role);
    return true;
  }

  checkAccess(userId, requiredRole) {
    if (!Object.prototype.hasOwnProperty.call(this.roleHierarchy, requiredRole)) return false;
    const userRole = this.permissions.get(String(userId)) || 'guest';
    if (!Object.prototype.hasOwnProperty.call(this.roleHierarchy, userRole)) return false;
    const userLevel = this.roleHierarchy[userRole];
    const requiredLevel = this.roleHierarchy[requiredRole];
    return userLevel >= requiredLevel;
  }

  getEffectiveRole(userId) {
    const role = this.permissions.get(String(userId)) || 'guest';
    if (!Object.prototype.hasOwnProperty.call(this.roleHierarchy, role)) return 'guest';
    return role;
  }
}

class RequestSanitizer {
  static sanitizePath(inputPath) {
    if (typeof inputPath !== 'string') return '/';
    let normalized;
    try {
      normalized = decodeURIComponent(inputPath);
    } catch (e) {
      return '/';
    }
    normalized = normalized.normalize('NFC');
    // Iteratively remove traversal sequences until stable
    let prev;
    do {
      prev = normalized;
      normalized = normalized.replace(/\.\./g, '').replace(/\/\//g, '/');
    } while (normalized !== prev);
    if (!normalized.startsWith('/')) normalized = '/' + normalized;
    // Whitelist allowed paths
    const allowedPaths = ['/login', '/admin/users', '/admin/config', '/profile'];
    if (!allowedPaths.includes(normalized)) return '/';
    return normalized;
  }

  static sanitizeUserId(uid) {
    if (typeof uid !== 'string') return null;
    const cleaned = uid.normalize('NFC').trim();
    if (cleaned.length === 0 || cleaned.length > 64) return null;
    if (!/^[a-zA-Z0-9_\-]+$/.test(cleaned)) return null;
    return cleaned;
  }

  static extractBearerToken(authHeader) {
    if (!authHeader || typeof authHeader !== 'string') return null;
    if (authHeader.length > 4096) return null;
    const parts = authHeader.split(' ');
    if (parts.length !== 2 || parts[0] !== 'Bearer') return null;
    if (!/^[A-Za-z0-9+/=]+$/.test(parts[1])) return null;
    return parts[1];
  }
}

class AdminAPI {
  constructor() {
    this.sessionStore = new SessionStore();
    this.acl = new AccessControl();
    this.auditLog = [];
  }

  handleRequest(req, res) {
    const parsed = url.parse(req.url, true);
    const path = RequestSanitizer.sanitizePath(parsed.pathname);
    const token = RequestSanitizer.extractBearerToken(
      req.headers['authorization']
    );

    this.logAccess(req, path);

    if (path === '/login') {
      return this.handleLogin(req, res, parsed.query);
    }

    const session = token ? this.sessionStore.verifyToken(token) : null;
    if (!session) {
      return this.sendError(res, 401, 'Unauthorized');
    }

    if (path === '/admin/users') {
      return this.handleAdminUsers(req, res, session);
    } else if (path === '/admin/config') {
      return this.handleAdminConfig(req, res, session);
    } else if (path === '/profile') {
      return this.handleProfile(req, res, session);
    }

    this.sendError(res, 404, 'Not Found');
  }

  handleLogin(req, res, query) {
    const userId = RequestSanitizer.sanitizeUserId(query.user);
    if (!userId) return this.sendError(res, 400, 'Invalid user');
    const token = this.sessionStore.generateToken(userId);
    this.sendJSON(res, 200, { token });
  }

  handleAdminUsers(req, res, session) {
    if (!this.acl.checkAccess(session.uid, 'admin')) {
      return this.sendError(res, 403, 'Forbidden');
    }
    this.sendJSON(res, 200, { users: Array.from(this.acl.permissions.entries()) });
  }

  handleAdminConfig(req, res, session) {
    if (!this.acl.checkAccess(session.uid, 'manager')) {
      return this.sendError(res, 403, 'Forbidden');
    }
    this.sendJSON(res, 200, { config: { maxUsers: 100 } });
  }

  handleProfile(req, res, session) {
    this.sendJSON(res, 200, {
      uid: session.uid,
      role: this.acl.getEffectiveRole(session.uid)
    });
  }

  logAccess(req, path) {
    this.auditLog.push({
      timestamp: Date.now(),
      ip: req.connection ? req.connection.remoteAddress : 'unknown',
      path: path,
      method: req.method
    });
    if (this.auditLog.length > 10000) {
      this.auditLog = this.auditLog.slice(-5000);
    }
  }

  sendJSON(res, code, data) {
    res.writeHead(code, {
      'Content-Type': 'application/json',
      'X-Content-Type-Options': 'nosniff'
    });
    res.end(JSON.stringify(data));
  }

  sendError(res, code, message) {
    this.sendJSON(res, code, { error: message });
  }
}

module.exports = { AdminAPI, SessionStore, AccessControl, RequestSanitizer };
